// /api/lifehacks.js — Daily life hack tips generated by Claude, cached until midnight.
//
// NOTE: The primary client (LifeHacks.jsx) now selects hacks directly from the
// bundled LifeHackLibrary (416 hacks, round-robin, no API needed). This endpoint
// is kept as an optional enhancement and for external consumers.
//
// Requires: ANTHROPIC_API_KEY env var
// Falls back to library-based selection when the key is absent.

import Anthropic from "@anthropic-ai/sdk";
import { HACK_LIBRARY } from "../src/LifeHackLibrary.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

const AREA_META = {
  Mind:               { emoji: "🧠" },
  Body:               { emoji: "💪" },
  Relationships:      { emoji: "❤️" },
  Work:               { emoji: "💼" },
  Finance:            { emoji: "💰" },
  Home:               { emoji: "🏡" },
  Digital:            { emoji: "📱" },
  "Weird & Wonderful":{ emoji: "🪄" },
};

function secondsUntilMidnight() {
  const now = new Date();
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);
  return Math.max(60, Math.floor((midnight - now) / 1000));
}

function todayString() {
  return new Date().toISOString().split("T")[0]; // YYYY-MM-DD
}

// Library-based fallback: deterministic per-day selection using day index
// Different prime offsets per category ensure categories don't cycle in lockstep.
const CATEGORY_PRIMES = [1, 7, 11, 13, 17, 19, 23, 29];
function fallbackForDate(dateStr) {
  const dayIndex = Math.floor(Date.parse(dateStr) / 86400000);
  const categories = Object.entries(HACK_LIBRARY);
  return categories.map(([area, hacks], ci) => {
    const idx = (dayIndex * CATEGORY_PRIMES[ci]) % hacks.length;
    const hack = hacks[idx];
    return { ...hack, area, areaEmoji: AREA_META[area]?.emoji ?? "✨" };
  });
}

// ── Main handler ──────────────────────────────────────────────────────────────

export default async function handler(req, res) {
  res.setHeader("Access-Control-Allow-Origin", "*");

  const today = todayString();
  const ttl = secondsUntilMidnight();

  const apiKey = process.env.ANTHROPIC_API_KEY;

  if (!apiKey) {
    res.setHeader("Cache-Control", `public, s-maxage=${ttl}, stale-while-revalidate=60`);
    return res.status(200).json({ date: today, hacks: fallbackForDate(today), source: "library" });
  }

  try {
    const client = new Anthropic({ apiKey });

    const response = await client.messages.create({
      model: "claude-haiku-4-5-20251001",
      max_tokens: 2048,
      messages: [{
        role: "user",
        content: `Today is ${today}. Generate exactly 8 daily life hacks for the "Seen" wellbeing app — one per life area.

Rules for each hack:
- Give it a memorable, specific name (e.g. "The Wooden Spoon Trick", "The 48-Hour Rule")
- Be CONCRETE and immediately actionable — something a person can try today
- Avoid generic advice like "drink more water" or "exercise regularly" — be specific and surprising
- The "why" must explain the actual science, psychology, or logic — not just restate the tip
- Pick a DIFFERENT sub-area each day — use the day number (${Math.floor(Date.parse(today) / 86400000)}) to vary your choices

Life areas and sub-areas to choose from (pick one sub-area per area):
1. Mind 🧠 → Focus, Stress, Sleep, Memory, Creativity, Clarity, Anxiety, Decision-making, Mindfulness, Learning
2. Body 💪 → Cooking, Exercise, Nutrition, Energy, Hydration, Posture, Digestion, Recovery, Flexibility, Breathing
3. Relationships ❤️ → Communication, Conflict, Friendship, Family, Kindness, Listening, Boundaries, Gratitude, Romance, Empathy
4. Work 💼 → Productivity, Meetings, Email, Planning, Deep Work, Breaks, Procrastination, Organisation, Negotiation, Focus
5. Finance 💰 → Saving, Budgeting, Spending, Investing, Debt, Shopping, Subscriptions, Tax, Credit, Salary
6. Home 🏡 → Organisation, Cleaning, Lighting, Clutter, Morning Routine, Air Quality, Sleep Space, Storage, Maintenance, Safety
7. Digital 📱 → Screen Time, Notifications, Social Media, Focus Mode, Sleep Hygiene, Privacy, Passwords, Backup, Email Inbox, Digital Clutter
8. Weird & Wonderful 🪄 → Kitchen, Cables, Travel, Laundry, DIY, Shopping, Nature, Stains, Car, Skills

Return ONLY valid JSON with no markdown fences:
{
  "date": "${today}",
  "hacks": [
    {
      "area": "Mind",
      "areaEmoji": "🧠",
      "subArea": "Sleep",
      "subAreaEmoji": "😴",
      "title": "The Warm Sock Trick",
      "hack": "Put on a pair of warm socks 30 minutes before bed...",
      "why": "Warm feet cause blood vessels to dilate, which signals your brain to lower core body temperature — the exact trigger for sleep onset."
    }
  ]
}`,
      }],
    });

    const text = response.content[0]?.text || "";
    const raw = text.match(/\{[\s\S]*\}/)?.[0];
    if (!raw) throw new Error("Claude returned no JSON object");

    const data = JSON.parse(raw);
    if (!Array.isArray(data.hacks) || data.hacks.length < 8) throw new Error("Incomplete hacks array");

    res.setHeader("Cache-Control", `public, s-maxage=${ttl}, stale-while-revalidate=60`);
    return res.status(200).json({ date: today, hacks: data.hacks, source: "claude" });

  } catch (err) {
    console.error("LifeHacks API error:", err.message);
    res.setHeader("Cache-Control", "public, s-maxage=300, stale-while-revalidate=60");
    return res.status(200).json({ date: today, hacks: fallbackForDate(today), source: "library" });
  }
}
